with versions as (

    select * from {{ ref('snp_dim_customer') }}

)

select
    versions.customer_id as customer_id,
    versions.customer_name as customer_name,
    versions.phone as phone,
    versions.nation_name as nation_name,
    versions.market_segment as market_segment,
    versions.account_balance as account_balance,
    cast(versions.dbt_valid_from as TIMESTAMP) as valid_from,
    cast(versions.dbt_valid_to as TIMESTAMP) as valid_to,
    versions.dbt_valid_to is null as is_current,
    cast(current_timestamp as TIMESTAMPTZ) as _updated_at
from versions

union all

